// @ts-check
// IntelliSense Pro: the TypeScript language service for JS and TS projects,
// one per project. typescript.js and lib/*.d.ts are generated by
// scripts/build-services.js. Paths in requests are relative to the app's
// Documents directory (projects/<name>/...); paths in answers are relative to
// the project, as the editor uses them.
'use strict';

const fs = require('fs');
const path = require('path');
const { serve } = require('../service');

// The supervisor sets PWD per run; process.cwd() is shared with every other run.
const ROOT = process.env.PWD || process.cwd();
/** @type {typeof import('typescript')} */
const ts = require('./typescript');

const SOURCE = /\.(m?[jt]sx?|c[jt]s)$/i;
const SKIP_DIRS = new Set(['node_modules', '.git', '.pylibs', '__pycache__', 'dist', 'build']);
const MAX_FILES = 3000;
const MAX_COMPLETIONS = 500;
const RESCAN_MS = 5000;

/** @param {string} rel e.g. projects/app/src/a.ts */
function split(rel) {
  const parts = rel.split('/');
  if (parts[0] !== 'projects' || parts.length < 3) throw new Error(`not a project file: ${rel}`);
  return { dir: path.join(ROOT, 'projects', parts[1]), file: path.join(ROOT, rel) };
}

/** @type {Map<string, ReturnType<typeof createProject>>} */
const projects = new Map();

function compilerOptions(dir) {
  for (const name of ['tsconfig.json', 'jsconfig.json']) {
    const configPath = path.join(dir, name);
    if (!fs.existsSync(configPath)) continue;
    const { config } = ts.readConfigFile(configPath, ts.sys.readFile);
    if (!config) continue;
    const parsed = ts.parseJsonConfigFileContent(config, ts.sys, dir);
    return { ...parsed.options, allowJs: parsed.options.allowJs ?? name === 'jsconfig.json' };
  }
  return {
    allowJs: true,
    checkJs: false,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.Preserve,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    jsx: ts.JsxEmit.ReactJSX,
    esModuleInterop: true,
    resolveJsonModule: true,
    skipLibCheck: true,
    strict: true,
    noEmit: true,
    lib: ['lib.es2023.d.ts', 'lib.dom.d.ts', 'lib.dom.iterable.d.ts'],
  };
}

/** @param {string} dir */
function scan(dir) {
  /** @type {string[]} */
  const out = [];
  const walk = (/** @type {string} */ d) => {
    let entries;
    try {
      entries = fs.readdirSync(d, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      if (out.length >= MAX_FILES) return;
      if (e.isDirectory()) {
        if (!SKIP_DIRS.has(e.name) && !e.name.startsWith('.')) walk(path.join(d, e.name));
      } else if (SOURCE.test(e.name) && !e.name.endsWith('.d.ts.map')) out.push(path.join(d, e.name));
    }
  };
  walk(dir);
  return out;
}

/** @param {string} dir */
function createProject(dir) {
  /** @type {Map<string, { text: string, version: number }>} */
  const open = new Map();
  let files = scan(dir);
  let scannedAt = Date.now();
  let options = compilerOptions(dir);
  const libDir = path.join(__dirname, 'lib');

  /** @type {import('typescript').LanguageServiceHost} */
  const host = {
    getCompilationSettings: () => options,
    getScriptFileNames: () => {
      if (Date.now() - scannedAt > RESCAN_MS) {
        files = scan(dir);
        scannedAt = Date.now();
      }
      return [...new Set([...files, ...open.keys()])];
    },
    getScriptVersion: (f) => {
      const doc = open.get(f);
      if (doc) return `o${doc.version}`;
      try {
        return `d${fs.statSync(f).mtimeMs}`;
      } catch {
        return 'missing';
      }
    },
    getScriptSnapshot: (f) => {
      const doc = open.get(f);
      if (doc) return ts.ScriptSnapshot.fromString(doc.text);
      if (!fs.existsSync(f)) return undefined;
      return ts.ScriptSnapshot.fromString(fs.readFileSync(f, 'utf8'));
    },
    getCurrentDirectory: () => dir,
    getDefaultLibFileName: (o) => path.join(libDir, ts.getDefaultLibFileName(o)),
    fileExists: (f) => open.has(f) || ts.sys.fileExists(f),
    readFile: (f) => open.get(f)?.text ?? ts.sys.readFile(f),
    readDirectory: ts.sys.readDirectory,
    directoryExists: ts.sys.directoryExists,
    getDirectories: ts.sys.getDirectories,
    realpath: ts.sys.realpath,
  };
  const service = ts.createLanguageService(host, ts.createDocumentRegistry());

  return {
    dir,
    service,
    /** @param {string} file @param {string} text */
    set(file, text) {
      const doc = open.get(file);
      if (doc && doc.text === text) return;
      open.set(file, { text, version: (doc?.version ?? 0) + 1 });
      if (/(ts|js)config\.json$/.test(file)) options = compilerOptions(dir);
    },
    /** @param {string} file */
    close(file) {
      open.delete(file);
    },
    text: (/** @type {string} */ file) => open.get(file)?.text ?? (fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : ''),
  };
}

/** @param {string} rel */
function projectFor(rel) {
  const { dir, file } = split(rel);
  let project = projects.get(dir);
  if (!project) {
    project = createProject(dir);
    projects.set(dir, project);
  }
  return { project, file };
}

/** A position in a file, for the editor: project-relative path, 1-based line and column. */
function location(project, file, start) {
  if (!file.startsWith(project.dir + path.sep)) return null;
  const program = project.service.getProgram();
  const source = program && program.getSourceFile(file);
  const text = source ? source.text : project.text(file);
  const lc = source ? source.getLineAndCharacterOfPosition(start) : ts.computeLineAndCharacterOfPosition(ts.computeLineStarts(text), start);
  const lineStart = ts.computeLineStarts(text)[lc.line] ?? 0;
  const lineEnd = text.indexOf('\n', lineStart);
  return {
    path: path.relative(project.dir, file).split(path.sep).join('/'),
    line: lc.line + 1,
    column: lc.character + 1,
    preview: text.slice(lineStart, lineEnd === -1 ? undefined : lineEnd).trim().slice(0, 200),
  };
}

/** @type {Record<string, string>} */
const KINDS = {
  function: 'function',
  'local function': 'function',
  method: 'method',
  constructor: 'method',
  getter: 'property',
  setter: 'property',
  property: 'property',
  var: 'variable',
  let: 'variable',
  const: 'constant',
  'local var': 'variable',
  parameter: 'variable',
  class: 'class',
  'local class': 'class',
  interface: 'interface',
  type: 'type',
  'type parameter': 'type',
  enum: 'enum',
  'enum member': 'enum',
  module: 'namespace',
  'external module name': 'namespace',
  keyword: 'keyword',
  alias: 'variable',
};

const text = (/** @type {readonly import('typescript').SymbolDisplayPart[] | undefined} */ parts) => ts.displayPartsToString(parts);

serve({
  // Full text of a file the app has open; it wins over the copy on disk.
  open({ path: rel, content }) {
    const { project, file } = projectFor(rel);
    project.set(file, content);
  },
  close({ path: rel }) {
    const { project, file } = projectFor(rel);
    project.close(file);
  },

  completions({ path: rel, offset }) {
    const { project, file } = projectFor(rel);
    const source = project.text(file);
    const result = project.service.getCompletionsAtPosition(file, offset, {
      includeCompletionsForModuleExports: false,
      includeCompletionsWithInsertText: true,
    });
    let from = offset;
    while (from > 0 && /[\w$]/.test(source[from - 1])) from--;
    if (!result) return { from, items: [] };
    // The list is filtered as the user types; trim it by the first letter so it stays small to send.
    const first = source.slice(from, offset)[0]?.toLowerCase();
    const entries = result.entries
      .filter((e) => !first || e.name[0]?.toLowerCase() === first)
      .sort((a, b) => (a.sortText < b.sortText ? -1 : a.sortText > b.sortText ? 1 : a.name.localeCompare(b.name)))
      .slice(0, MAX_COMPLETIONS);
    return {
      from,
      items: entries.map((e) => ({ label: e.name, type: KINDS[e.kind] ?? 'text', detail: e.kindModifiers?.includes('deprecated') ? 'deprecated' : undefined })),
    };
  },

  hover({ path: rel, offset }) {
    const { project, file } = projectFor(rel);
    const info = project.service.getQuickInfoAtPosition(file, offset);
    if (!info) return null;
    const docs = text(info.documentation);
    const tags = (info.tags || []).map((t) => `@${t.name}${t.text ? ` ${text(t.text)}` : ''}`).join('\n');
    return {
      text: [text(info.displayParts), docs, tags].filter(Boolean).join('\n\n'),
      from: info.textSpan.start,
      to: info.textSpan.start + info.textSpan.length,
    };
  },

  definition({ path: rel, offset }) {
    const { project, file } = projectFor(rel);
    const defs = project.service.getDefinitionAtPosition(file, offset) || [];
    return defs.map((d) => location(project, d.fileName, d.textSpan.start)).filter(Boolean);
  },

  references({ path: rel, offset }) {
    const { project, file } = projectFor(rel);
    const refs = project.service.getReferencesAtPosition(file, offset) || [];
    return refs.map((r) => location(project, r.fileName, r.textSpan.start)).filter(Boolean);
  },

  // Edits that rename the symbol at offset everywhere in the project.
  rename({ path: rel, offset, newName }) {
    const { project, file } = projectFor(rel);
    const info = project.service.getRenameInfo(file, offset, { allowRenameOfImportPath: false });
    if (!info.canRename) throw new Error(info.localizedErrorMessage);
    // Without prefix and suffix text, renaming at an import renames the declaration too, not just a local alias.
    const locations = project.service.findRenameLocations(file, offset, false, false, { providePrefixAndSuffixTextForRename: false }) || [];
    /** @type {Map<string, { from: number, to: number, insert: string }[]>} */
    const byFile = new Map();
    for (const l of locations) {
      if (!l.fileName.startsWith(project.dir + path.sep)) continue;
      const rel2 = path.relative(project.dir, l.fileName).split(path.sep).join('/');
      const edits = byFile.get(rel2) || [];
      edits.push({ from: l.textSpan.start, to: l.textSpan.start + l.textSpan.length, insert: `${l.prefixText || ''}${newName}${l.suffixText || ''}` });
      byFile.set(rel2, edits);
    }
    return [...byFile].map(([p, edits]) => ({ path: p, edits }));
  },

  diagnostics({ path: rel }) {
    const { project, file } = projectFor(rel);
    const source = project.text(file);
    const starts = ts.computeLineStarts(source);
    const all = [...project.service.getSyntacticDiagnostics(file), ...project.service.getSemanticDiagnostics(file), ...project.service.getSuggestionDiagnostics(file)];
    return all
      .filter((d) => d.start !== undefined && (d.category !== ts.DiagnosticCategory.Suggestion || d.reportsUnnecessary || d.reportsDeprecated))
      .map((d) => {
        const start = /** @type {number} */ (d.start);
        const end = start + (d.length || 1);
        const a = ts.computeLineAndCharacterOfPosition(starts, start);
        const b = ts.computeLineAndCharacterOfPosition(starts, end);
        return {
          line: a.line + 1,
          column: a.character + 1,
          endLine: b.line + 1,
          endColumn: b.character + 1,
          severity: d.category === ts.DiagnosticCategory.Error ? 'error' : d.category === ts.DiagnosticCategory.Warning ? 'warning' : 'info',
          message: `${ts.flattenDiagnosticMessageText(d.messageText, '\n')} (ts${d.code})`,
        };
      });
  },
});
